  /* GitHub */
  "gh.menu": ["GitHub…", "GitHub…"],
  "gh.title": ["GitHub: проект в репозитории", "GitHub: project in a repository"],
  "gh.err.auth": ["GitHub не принял токен: он неверный или истёк. Создайте новый и войдите снова.", "GitHub rejected the token: it is wrong or expired. Create a new one and sign in again."],
  "gh.err.rate": ["Лимит запросов GitHub исчерпан. Программа повторит попытку позже.", "The GitHub request limit is used up. The app will try again later."],
  "gh.err.forbidden": ["У токена нет доступа к этому репозиторию или нет права записи (нужно Contents: Read and write).", "The token has no access to this repository or no write permission (Contents: Read and write is needed)."],
  "gh.err.notfound": ["Репозиторий или файл не найден, либо у токена нет к нему доступа.", "The repository or file was not found, or the token has no access to it."],
  "gh.x.case": ["Токен видит репозиторий под названием «{0}»: впишите его точно так.", "The token sees the repository as “{0}”: enter it exactly like that."],
  "gh.x.owner": ["Репозиторий с таким названием лежит у другого владельца: {0}. Вы ввели {1}.", "A repository with that name belongs to another owner: {0}. You entered {1}."],
  "gh.x.login": ["Ваш логин на GitHub: {0}, а вы ввели {1}. Владелец должен быть логином (или организацией), а не именем из профиля.", "Your GitHub login is {0}, but you entered {1}. The owner must be a login (or organization), not a profile name."],
  "gh.x.near": ["Похожие: {0}.", "Similar: {0}."],
  "gh.x.sees": ["Токен сейчас видит репозиториев: {0} ({1}), а нужного среди них нет.", "The token currently sees {0} repositories ({1}), and the one you need is not among them."],
  "gh.x.none": ["Токен не видит ни одного репозитория: при создании не выбран репозиторий, либо токен просрочен.", "The token sees no repositories at all: none was selected when it was created, or it has expired."],
  "gh.x.fix": ["Что сделать: GitHub → Settings → Developer settings → Fine-grained tokens → ваш токен → «Repository access» → «Only select repositories» → добавить «{0}»; в «Permissions» → «Repository permissions» поставить Contents: Read and write. Затем снова «Подключить и отправить».", "Fix: GitHub → Settings → Developer settings → Fine-grained tokens → your token → “Repository access” → “Only select repositories” → add “{0}”; under Permissions → Repository permissions set Contents: Read and write. Then press “Connect and upload” again."],
  "gh.err.server": ["GitHub ответил ошибкой (код {0}). Попробуйте позже.", "GitHub answered with an error (code {0}). Try again later."],
  "gh.err.net": ["Нет связи с GitHub. Проверьте интернет. Если вы открыли программу в браузере или в Claude, запросы к GitHub там заблокированы: используйте программу для компьютера (github.com/Gamers-U/VNmap/releases/latest).", "Cannot reach GitHub. Check your internet. If you opened the app in a browser or inside Claude, GitHub requests are blocked there: use the desktop app (github.com/Gamers-U/VNmap/releases/latest)."],
  "gh.err.token": ["Это не похоже на токен GitHub.", "This does not look like a GitHub token."],
  "gh.err.notfile": ["По этому пути в репозитории лежит не файл.", "There is no file at this path in the repository."],
