  "gh.err.readonly": ["У вас нет права записи в этот репозиторий.", "You have no write access to this repository."],
  "gh.err.repo": ["Укажите репозиторий как владелец/название.", "Enter the repository as owner/name."],
  "gh.err.nofile": ["Файл «{0}» не найден в репозитории.", "The file “{0}” was not found in the repository."],
  "gh.commit": ["Карта новеллы: «{0}»", "Novel Map: “{0}”"],
