  "gh.joined": ["Проект взят из репозитория", "Project taken from the repository"],
  "gh.signed": ["Вы вошли в GitHub как {0}", "Signed in to GitHub as {0}"],
  "ghl.h": ["Вход через GitHub", "Sign in with GitHub"],
  "ghl.t": ["Самый простой способ: нажмите кнопку, программа покажет короткий код и откроет страницу GitHub. Введите код там и подтвердите вход. Пароль и токен вводить не нужно, токен программа получит сама и сохранит только на вашем компьютере.", "The easy way: press the button, the program shows a short code and opens the GitHub page. Enter the code there and confirm. You do not type a password or a token: the program gets the token itself and keeps it only on your computer."],
  "ghl.btn": ["Войти через GitHub", "Sign in with GitHub"],
  "ghl.pub": ["Только открытые репозитории", "Public repositories only"],
  "ghl.pub.h": ["Включите, если проект лежит в открытом репозитории: программа получит доступ только к открытым. Для закрытых оставьте выключенным.", "Turn on if your project is in a public repository: the program then gets access to public ones only. Leave it off for private repositories."],
  "ghl.code.h": ["Ваш код", "Your code"],
  "ghl.code.t": ["Введите этот код на странице GitHub и нажмите «Authorize». Страница открылась сама, код уже в буфере обмена.", "Enter this code on the GitHub page and press Authorize. The page opened by itself, the code is already on the clipboard."],
  "ghl.copy": ["Скопировать код", "Copy the code"],
  "ghl.copied": ["Код скопирован", "Code copied"],
  "ghl.open": ["Открыть страницу GitHub", "Open the GitHub page"],
  "ghl.wait": ["Жду подтверждения на сайте GitHub…", "Waiting for you to confirm on the GitHub site…"],
  "ghl.left": ["Код действует ещё {0}", "The code is valid for {0} more"],
  "ghl.cancel": ["Отмена", "Cancel"],
  "ghl.manual": ["Войти по токену вручную", "Sign in with a token by hand"],
  "ghl.old": ["Чтобы входить без токена, обновите оболочку программы (Настройки → кнопка «Обновить оболочку»). Вход по токену работает как раньше.", "To sign in without a token, update the program shell (Settings, the Update shell button). Signing in with a token works as before."],
  "ghl.e.expired": ["Время кода вышло. Нажмите «Войти через GitHub» ещё раз.", "The code has expired. Press Sign in with GitHub again."],
  "ghl.e.denied": ["Вход отклонён на сайте GitHub. Если это вышло случайно, нажмите «Войти через GitHub» ещё раз.", "The sign-in was declined on the GitHub site. If that was a mistake, press Sign in with GitHub again."],
  "ghl.e.app": ["GitHub не принял запрос программы ({0}). Если вы владелец приложения, проверьте, что в его настройках на GitHub включён Device Flow. Пока можно войти по токену.", "GitHub did not accept the program request ({0}). If you own the application, check that Device Flow is on in its settings on GitHub. You can sign in with a token meanwhile."],
  "ghl.e.network": ["Нет связи с GitHub. Проверьте интернет и повторите.", "No connection to GitHub. Check the internet and try again."],
  "ghl.e.server": ["GitHub сейчас не отвечает ({0}). Повторите позже.", "GitHub is not answering right now ({0}). Try again later."],
  "ghl.e.verify": ["GitHub выдал доступ, но программа не смогла его проверить: {0}", "GitHub granted access but the program could not check it: {0}"],
  "ghl.e.other": ["Не удалось войти через GitHub ({0}). Можно войти по токену.", "Could not sign in with GitHub ({0}). You can sign in with a token."],
  "gh.pub.q": ["Репозиторий публичный", "The repository is public"],
  "gh.pub.t": ["Репозиторий {0} открыт для всех: любой человек в интернете сможет прочитать вашу новеллу. Для проекта лучше закрытый (Private) репозиторий. Всё равно подключить?", "The repository {0} is open to everyone: anybody on the internet will be able to read your novel. A private repository is better for a project. Connect anyway?"],
  "gh.pub.ok": ["Подключить публичный", "Connect the public one"],
  "gh.join.q": ["Заменить текущий проект?", "Replace the current project?"],
  "gh.join.t": ["Вместо открытого сейчас проекта будет загружен проект из репозитория. Если в текущем есть нужное, сначала сохраните его в файл.", "The project from the repository will be loaded instead of the one open now. If the current one has something you need, save it to a file first."],
  "gh.join.ok": ["Взять из репозитория", "Take from the repository"],
  "gh.c.exists": ["В репозитории уже есть проект", "The repository already has a project"],
  "gh.c.exists.t": ["По этому пути лежит проект «{0}» ({1} блоков). Что сделать?", "There is a project “{0}” ({1} blocks) at this path. What should happen?"],
  "gh.c.other": ["В репозитории лежит другой проект", "The repository holds a different project"],
  "gh.c.other.t": ["По этому пути лежит другой проект: «{0}» ({1} блоков). Заменить его вашим или взять его себе?", "A different project lies at this path: “{0}” ({1} blocks). Replace it with yours or take it?"],
  "gh.c.title": ["Правки с двух сторон не склеились", "The edits from both sides could not be merged"],
  "gh.c.t": ["Одно и то же место изменено и у вас, и в репозитории. Выберите, чью версию оставить.", "The same place was changed both here and in the repository. Choose whose version to keep."],
  "gh.c.safe": ["Старая версия в репозитории не пропадёт: она останется в истории, и её можно вернуть. Ваши несохранённые правки при выборе версии из GitHub пропадут, поэтому при сомнении сначала сохраните свою копию в файл.", "The old version in the repository is not lost: it stays in the history and can be restored. Your unsent edits are lost if you take the GitHub version, so if in doubt save your copy to a file first."],
  "gh.c.take": ["Взять версию из GitHub", "Take the GitHub version"],
  "gh.c.mine": ["Отправить мою версию", "Send my version"],
  "gh.c.file": ["Сохранить мою копию в файл", "Save my copy to a file"],
