  'drive.rb.ok': ['Вернуть', 'Restore'], 'drive.rb.btn': ['Вернуть', 'Restore'], 'drive.restored': ['Копия восстановлена', 'Backup restored'],
  'drive.acct.new': ['Вы вошли в другой аккаунт Google ({0}) или с другим ключом. Проект будет записан в его Диск заново; файлы на прежнем Диске остаются как были.', 'You signed in with a different Google account ({0}) or key. The project will be written to its Drive again; the files on the previous Drive stay as they were.'],
