  'fx.undef.hint': ['Этого имени нет в Ren\'Py и оно нигде не описано: игра остановится на нём. Опишите эффект в редакторе.', 'This name is not in Ren\'Py and is defined nowhere: the game would stop on it. Define it in the editor.'],
  'fx.edit': ['Эффект «{0}»', 'Effect “{0}”'], 'fx.edit.btn': ['Править', 'Edit'], 'fx.define': ['Описать…', 'Define…'], 'fx.create': ['Создать', 'Create'], 'fx.name': ['Имя в скрипте', 'Name in the script'],
