  'fx.tpl': ['Заготовка', 'Template'], 'fx.code': ['Код для Ren\'Py', 'Ren\'Py code'], 'fx.preview': ['Как это выглядит', 'How it looks'], 'fx.preview.hint': ['Приблизительный показ: точный вид и скорость видны только в игре.', 'An approximation: the exact look and speed show only in the game.'],
