  'cmp.fx.badname': ['Эффект «{0}» пропущен: имя должно быть латиницей без пробелов', 'Effect “{0}” skipped: the name must be Latin letters without spaces'],
  'cmp.fx.dup': ['Эффект «{0}» пропущен: такое имя уже занято (эффект, персонаж или переменная)', 'Effect “{0}” skipped: the name is taken (effect, character or variable)'],
